                {"name": "debug_variantes", "code": "for v in ['1', 'true', 'TRUE', 'yes', 'on']:\n    assert charger_config({'DATABASE_URL': 'x', 'DEBUG': v})['debug'] is True\nassert charger_config({'DATABASE_URL': 'x', 'DEBUG': 'false'})['debug'] is False"},
